-- Self-contained, idempotent, post-checked.

BEGIN;

-- Multi-Spindle Machining - Bar Stock
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Multi-Spindle Machining - Bar Stock$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Multi-Spindle Machining - Bar Stock$q$, 'process', 'single', false, true, true, $q$The bar bought per part. The bar is the part's OD (or across flats) plus the stock allowance on each side, snapped up to the location's preferred size; each part takes its length, the parting tool's width (tblPartingRingWidth, by the bar's diameter) and the facing stock (minStockAllowance). A bar of standardStockLength yields as many parts as fit after the remnant the bar feeder cannot use, and each part carries its share of the whole bar. Priced per kg for the bar's form (material_stock_prices).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The bar bought per part. The bar is the part's OD (or across flats) plus the stock allowance on each side, snapped up to the location's preferred size; each part takes its length, the parting tool's width (tblPartingRingWidth, by the bar's diameter) and the facing stock (minStockAllowance). A bar of standardStockLength yields as many parts as fit after the remnant the bar feeder cannot use, and each part carries its share of the whole bar. Priced per kg for the bar's form (material_stock_prices).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Length$q$, $q$Part Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Bar Section Area$q$, $q$Bar Section Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Parting Width$q$, $q$Parting Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Facing Stock$q$, $q$Facing Stock (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Bar Length$q$, $q$Bar Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Bar Remnant$q$, $q$Bar Remnant (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Density$q$, $q$Density (kg/m³)$q$, $q$number$q$, $q$kg/m³$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Price per kg$q$, $q$Price per kg (USD/kg)$q$, $q$number$q$, $q$USD/kg$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Length per Part$q$, $q$Length per Part (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Part Length} + {Parting Width} + {Facing Stock}$q$, 9, false),
    (v_id, $q$Parts per Bar$q$, $q$Parts per Bar$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, floor(({Bar Length} - {Bar Remnant}) / {Length per Part}))$q$, 10, false),
    (v_id, $q$Bar Mass$q$, $q$Bar Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Bar Length} * {Bar Section Area} * {Density} / 1000000000$q$, 11, false),
    (v_id, $q$Mass per Part$q$, $q$Mass per Part (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Bar Mass} / {Parts per Bar}$q$, 12, false),
    (v_id, $q$Material Cost$q$, $q$Material Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Mass per Part} * {Price per kg}$q$, 13, false);
END
$calc$;

-- Multi-Spindle Machining - Cycle
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Multi-Spindle Machining - Cycle$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Multi-Spindle Machining - Cycle$q$, 'process', 'single', false, true, true, $q$One part per index. Every station of the machine cuts at once, so the cycle is set by the slowest station (its operations, split across the spindles and their slides by the station plan, each with its tool positioning), plus the index: the drum turns, the part transfers to the back-work spindle, the bar feeds and the spindles synchronize.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$One part per index. Every station of the machine cuts at once, so the cycle is set by the slowest station (its operations, split across the spindles and their slides by the station plan, each with its tool positioning), plus the index: the drum turns, the part transfers to the back-work spindle, the bar feeds and the spindles synchronize.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Slowest Station$q$, $q$Slowest Station (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Drum Index Time$q$, $q$Drum Index Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Transfer Time$q$, $q$Transfer Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Stock Feed Time$q$, $q$Stock Feed Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Speed Synchronization Time$q$, $q$Speed Synchronization Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Index Time$q$, $q$Index Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Drum Index Time} + {Transfer Time} + {Stock Feed Time} + {Speed Synchronization Time}$q$, 6, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Slowest Station} + {Index Time}$q$, 7, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Multi-Spindle Machining - Cycle$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Multi-Spindle Machining$q$ AND operation IN ($q$Simultaneous Turning$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Multi-Spindle Machining - Bar Stock$q$, 13, 0),
    ($q$Multi-Spindle Machining - Cycle$q$, 7, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Multi-Spindle Machining$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1095: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
